    QVERIFY(PartitionApfsWriter::buildImageOnlyFormatImage(
                {.image_path = path,
                 .target_container_bytes = 64ULL * 1024ULL * 1024ULL,
                 .block_size_bytes = 4096,
                 .volume_name = QStringLiteral("CIB"),
                 .options = options})
                .ok);
